<?php require dirname(__DIR__).'/db.php';header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');$method=$_SERVER['REQUEST_METHOD'];function out($data,$code=200){http_response_code($code);echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;}if($method==='GET'){ $rows=$pdo->query('SELECT id,event_name,event_date,venue,category,description,status FROM events WHERE deleted_at IS NULL ORDER BY event_date')->fetchAll();out(['ok'=>true,'data'=>$rows]);}if(empty($_SESSION['user'])||$_SESSION['user']['role']!=='admin')out(['ok'=>false,'error'=>'Admin login required'],403);$input=json_decode(file_get_contents('php://input'),true)??$_POST;$action=$input['action']??'';if($action==='create'||$action==='update'){$name=trim($input['event_name']??'');$date=$input['event_date']??'';$venue=trim($input['venue']??'');if(!$name||!$date||!$venue)out(['ok'=>false,'error'=>'Name, date and venue are required'],422);if($action==='create'){$s=$pdo->prepare('INSERT INTO events(event_name,event_date,venue) VALUES(?,?,?)');$s->execute([$name,$date,$venue]);audit($pdo,'api_event_create',$name);out(['ok'=>true,'id'=>$pdo->lastInsertId()],201);}else{$id=(int)($input['id']??0);$s=$pdo->prepare('UPDATE events SET event_name=?,event_date=?,venue=? WHERE id=? AND deleted_at IS NULL');$s->execute([$name,$date,$venue,$id]);audit($pdo,'api_event_update','Event ID '.$id);out(['ok'=>true]);}}if($action==='delete'){$id=(int)($input['id']??0);$s=$pdo->prepare('UPDATE events SET deleted_at=NOW() WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);audit($pdo,'api_event_delete','Event ID '.$id);out(['ok'=>true]);}out(['ok'=>false,'error'=>'Unsupported action'],400);?>